mapper.select:
SELECT f.id, f.name, f.product_name, f.product_merge_code, f.product_specification, COALESCE (MAX(CASE WHEN v.enable = 1 THEN v.version_no END), null ) AS enableVersion FROM bm_product_formula f JOIN bm_resource_permission p ON p.resource_id = f.id JOIN bm_product_formula_version v ON v.product_formula_id = f.id WHERE f.is_deleted = 0
AND p.dept_id in
#{deptId}
AND f.product_id = #{productId}
and f.name like concat('%',#{name},'%')
group by f.id order by f.create_time desc

SELECT DISTINCT f.name AS productFormulaName, v.id AS productFormulaVersionId, v.version_no AS productFormulaVersionNo FROM bm_product_formula f JOIN bm_resource_permission p ON p.resource_id = f.id JOIN bm_product_formula_version v ON v.product_formula_id = f.id WHERE f.is_deleted = 0 AND f.product_id = #{productId} AND v.ENABLE = TRUE
AND p.dept_id in
#{deptId}

SELECT DISTINCT v.id FROM bm_product_formula f JOIN bm_resource_permission p ON p.resource_id = f.id JOIN bm_product_formula_version v ON v.product_formula_id = f.id WHERE f.is_deleted = 0 and v.is_deleted = 0 and v.`status` = '1'
AND p.dept_id in
#{deptId}
